<script lang="ts">
  import type {AppData} from '#lib/client/types.ts';import {permitted} from '#lib/client/api.ts';import Icon from './Icon.svelte';let {data}:{data:AppData}=$props();
  const slug=$derived(data.module?.slug||'');const routes=$derived(['customers','inquiries','quotes','orders'].includes(slug)?[{slug:'customers',label:'Kunde',permission:'crm'},{slug:'inquiries',label:'Anfrage',permission:'crm'},{slug:'quotes',label:'Angebot',permission:'sales'},{slug:'orders',label:'Auftrag',permission:'orders'}]:['suppliers','products','price-imports','purchase-orders','stock'].includes(slug)?[{slug:'suppliers',label:'Lieferant',permission:'purchasing'},{slug:'products',label:'Produkt',permission:'catalog'},{slug:'purchase-orders',label:'Bestellung',permission:'purchasing'},{slug:'stock',label:'Lager',permission:'inventory'}]:[]);
